import React, { useState, useEffect } from 'react';
import './styles.scss';
import { Link } from 'react-router-dom';

import logo from '../../assets/images/logo/logo-footer.png';
import MagicLogo from '../../assets/images/logo/magic-logo.png';
import FourLogo from '../../assets/images/logo/four-logo.png';
import JupiterLogo from '../../assets/images/logo/jupiter-logo.svg';

function Footer() {
  const [isVisible, setIsVisible] = useState(false);

  const scrollToTop = () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  useEffect(() => {
    const toggleVisibility = () => setIsVisible(window.pageYOffset > 500);
    window.addEventListener('scroll', toggleVisibility);
    return () => window.removeEventListener('scroll', toggleVisibility);
  }, []);

  return (
    <footer className="footer">
      <div className="footer-inner">
        <div className="tf-container">
          <div className="row">
            {/* 좌측: 로고 + 텍스트 */}
            <div className="widget widget-infor">
              <div className="logo">
                <img id="logo_footer" src={logo} alt="OrcaXP" />
              </div>
            </div>

            {/* 우측: 거래소 로고 */}
            <div className="exchange-logos">
                  <li>
                    <Link to="https://x.com/4pandabyte">
                      <i className="fa-brands fa-x-twitter"></i>
                    </Link>
                  </li>
                  {/* 교체된 부분 */}
                  <li>
                    <Link to="https://magiceden.io/marketplace/4pandabyte" target="_blank" rel="noopener noreferrer">
                      <img src={MagicLogo} alt="Magic Eden" className="social-img" />
                    </Link>
                  </li>
                  <li>
                    <Link to="https://four.io/token/4pandabyte" target="_blank" rel="noopener noreferrer">
                      <img src={FourLogo} alt="Four Platform" className="social-img" />
                    </Link>
                  </li>
            </div>
          </div>
        </div>
      </div>

      {/* 하단 copyright + 소셜 */}
      <div className="bottom-inner">
        <div className="tf-container">
          <div className="row">
            <div className="col-md-12">
              <div className="bottom">
                <p className="copy-right">4 Panda Byte 2025 - ALL rights reserved</p>

                <ul className="social-item">
                  {/* <li>
                    <Link to="">
                      <i className="icon-fl-vt"></i>
                    </Link>
                  </li> */}
                  {/* <li>
                    <Link to="https://x.com/4pandabyte">
                      <i className="fa-brands fa-x-twitter"></i>
                    </Link>
                  </li> */}
                  {/* <li>
                    <Link to="">
                      <i className="fab fa-telegram-plane"></i>
                    </Link>
                  </li>
                  <li>
                    <Link to="https://www.instagram.com/orcaxp777">
                      <i className="fab fa-instagram"></i>
                    </Link>
                  </li> */}
                  {/* <li>
                    <Link to="">
                      <i className="fab fa-youtube"></i>
                    </Link>
                  </li>
                  <li>
                    <Link to="">
                      <i className="icon-fl-tik-tok-2"></i>
                    </Link>
                  </li> */}
                </ul>
              </div>
            </div>
          </div>
        </div>
      </div>

      {isVisible && <Link onClick={scrollToTop} to="#" id="scroll-top"></Link>}
    </footer>
  );
}

export default Footer;
