import React, { useEffect, useMemo, useState } from "react";
import "./wizard.scss";
// --- 변경된 부분 ---
// Firebase 관련 모듈을 가져옵니다.
import { GoogleAuthProvider, signInWithPopup } from "firebase/auth";
import { auth } from "./firebase"; // 위에서 만든 firebase.js 파일을 가져옵니다.
// --- 변경된 부분 끝 ---


// ---- API endpoints (프론트 .env에서 덮어쓰기 가능) ----
const API_BASE = process.env.REACT_APP_API_URL || "http://localhost:8080";
const API_HEALTH = `${API_BASE}/api/health`;
// const API_GOOGLE_VERIFY = `${API_BASE}/api/google/verify`; // Firebase가 검증을 대신하므로 필요 없어질 수 있습니다.
const API_ISSUE_VOUCHER = `${API_BASE}/api/claim/issue-voucher`;


export default function OXPclaimWizard() {
  const [step, setStep] = useState(0);

  // Google
  const [googleOk, setGoogleOk] = useState(false);
  const [googleEmail, setGoogleEmail] = useState("");
  const [googleSub, setGoogleSub] = useState("");
  // const [gisReady, setGisReady] = useState(false); // --- 삭제된 부분 ---

  // X / Wallet
  const [xOk, setXOk] = useState(false);
  const [wallet, setWallet] = useState(null);
  const [walletSig, setWalletSig] = useState(null);

  // Voucher
  const [voucher, setVoucher] = useState(null);

  // UI
  const [log, setLog] = useState([]);
  const [isLoading, setIsLoading] = useState(false);

  const addLog = (msg) =>
    setLog((prev) => [...prev, `[${new Date().toLocaleTimeString()}] ${msg}`]);

  // Next 버튼 활성 조건
  const canNext = useMemo(() => {
    if (step === 0) return googleOk; // Google OK
    if (step === 1) return xOk; // X OK
    if (step === 2) return wallet && walletSig; // Wallet + Sign OK
    if (step === 3) return Boolean(voucher); // Voucher OK
    return false;
  }, [step, googleOk, xOk, wallet, walletSig, voucher]);

  // --- 삭제된 부분 ---
  // Google Identity Services 스크립트 로드는 더 이상 필요 없습니다.
  // useEffect(() => { ... });
  // --- 삭제된 부분 끝 ---

  // --- 변경된 부분 ---
  // Google 로그인 (Firebase 사용)
  const doGoogle = async () => {
    const provider = new GoogleAuthProvider();
    try {
      // 팝업창으로 Google 로그인을 요청합니다.
      const result = await signInWithPopup(auth, provider);
      const user = result.user;

      // 로그인 성공 시 상태를 업데이트합니다.
      setGoogleOk(true);
      setGoogleEmail(user.email);
      // Firebase의 UID는 Google의 sub와 동일한 역할을 합니다.
      setGoogleSub(user.uid);
      addLog(`✅ Google verified: ${user.email}`);

      // (선택 사항) 만약 백엔드에서 추가 검증이 필요하다면,
      // 아래와 같이 Firebase ID 토큰을 백엔드로 보낼 수 있습니다.
      // const idToken = await user.getIdToken();
      // await fetch(API_GOOGLE_VERIFY, {
      //   method: "POST",
      //   headers: { "Content-Type": "application/json" },
      //   body: JSON.stringify({ idToken: idToken }),
      // });

    } catch (error) {
      console.error("Firebase Google sign-in error", error);
      const errorCode = error.code;
      const errorMessage = error.message;
      addLog(`❌ Google login error: ${errorCode} - ${errorMessage}`);
      alert("Google login failed: " + errorMessage);
    }
  };
  // --- 변경된 부분 끝 ---

  // ---- Mock: X / Wallet / Signature / Claim ----
  const doTwitter = async () => {
    setXOk(true);
    addLog("✅ X verification complete (mock)");
  };

  const connectWallet = async () => {
    setWallet("FAKE_WALLET_BASE58");
    addLog("🔗 Wallet connected (mock)");
  };

  const signWallet = async () => {
    setWalletSig("FAKE_SIGNATURE_BASE58");
    addLog("🖋️ Wallet signed (mock)");
  };

  const issueVoucher = async () => {
    if (!wallet || !googleOk || !xOk) {
      return alert("Please complete all verification steps first.");
    }
    setIsLoading(true);
    try {
      const payload = {
        googleSub: googleSub || "mock-google-sub",
        xUserId: "mock-x-user",
        wallet,
      };

      const res = await fetch(API_ISSUE_VOUCHER, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });

      if (!res.ok) throw new Error(`Server ${res.status}`);

      const data = await res.json();
      if (data.ok) {
        setVoucher(data.voucher);
        addLog(`🎟️ Voucher issued: ${String(data.voucher).slice(0, 12)}… (ttl ${data.ttlMin}m)`);
      } else {
        throw new Error(data.error || "Unknown error");
      }
    } catch (err) {
      console.error(err);
      addLog(`❌ Failed to issue voucher: ${err.message}`);
      alert("Issue voucher failed: " + err.message);
    } finally {
      setIsLoading(false);
    }
  };

  const claimOnchain = async () => {
    if (!voucher) return alert("Voucher missing!");
    alert("🎉 (Demo) On-chain claim executed!");
    addLog("🚀 On-chain claim simulated");
  };

  // ---- Dev test: health ----
  const testHealth = async () => {
    try {
      const res = await fetch(API_HEALTH);
      const data = await res.json();
      addLog(`🌐 API health: ok=${data.ok}`);
    } catch (err) {
      addLog("❌ Health check failed: " + err.message);
    }
  };

  // ---- Step screens ----
  const screens = [
    {
      title: "① Google Verification",
      desc:
        "Sign in with Google to ensure one-time participation (prevents duplicates)." +
        (googleEmail ? ` Logged in as: ${googleEmail}` : ""),
      body: (
        <button className="btn" onClick={doGoogle} disabled={googleOk}>
          {googleOk ? "Google Verified ✅" : "Sign in with Google"}
        </button>
      ),
    },
    {
      title: "② X Verification",
      desc: "Follow OrcaXP on X and Like/Retweet the designated post.",
      body: (
        <button className="btn" onClick={doTwitter} disabled={xOk}>
          {xOk ? "Follow + Like/RT Verified ✅" : "Connect X & Verify"}
        </button>
      ),
    },
    {
      title: "③ Wallet Connection & Signature",
      desc: "Connect your wallet and sign a verification message to confirm ownership.",
      body: (
        <>
          <div className="row">
            <button className="btn" onClick={connectWallet}>
              {wallet ? "Wallet Connected ✅" : "Connect Wallet"}
            </button>
            <button className="btn btn--ghost" onClick={signWallet} disabled={!wallet}>
              {walletSig ? "Signed ✅" : "Sign Ownership"}
            </button>
          </div>
          <p className="meta">
            {wallet ? `Wallet: ${wallet.slice(0, 6)}...${wallet.slice(-6)}` : "Not connected"}
          </p>
        </>
      ),
    },
    {
      title: "④ Voucher Issuance",
      desc: "Once all verifications are complete, you can issue a claim voucher.",
      body: (
        <>
          <button
            className="btn btn--primary"
            onClick={issueVoucher}
            disabled={isLoading || Boolean(voucher)}
          >
            {isLoading ? "Issuing..." : voucher ? "Voucher Issued ✅" : "Issue Voucher"}
          </button>
          {voucher && <p className="meta">Voucher ready. You can claim your tokens now.</p>}
        </>
      ),
    },
    {
      title: "⑤ Claim 7,777 $OXP",
      desc: "Use your voucher to claim 7,777 $OXP. (On-chain transaction required)",
      body: (
        <button className="btn btn--success" onClick={claimOnchain} disabled={!voucher}>
          Claim Now
        </button>
      ),
    },
  ];

  const goNext = () => setStep((s) => Math.min(s + 1, screens.length - 1));
  const goPrev = () => setStep((s) => Math.max(s - 1, 0));

  return (
    <div className="wizard">
      {/* 상단 메인 타이틀 */}
      <h1 className="main-title">🎁 Claim 7,777 $OXP</h1>

      {/* 진행 점 표시 */}
      <div className="wizard__progress">
        {screens.map((_, i) => (
          <div
            key={i}
            className={["wizard__dot", i < step ? "done" : "", i === step ? "current" : ""]
              .filter(Boolean)
              .join(" ")}
          >
            {i + 1}
          </div>
        ))}
      </div>

      {/* 카드 */}
      <div className="wizard__card">
        <h2 className="title">{screens[step].title}</h2>
        <p className="desc">{screens[step].desc}</p>
        <div className="body">{screens[step].body}</div>

        <div className="wizard__nav">
          <button className="btn btn--ghost" onClick={goPrev} disabled={step === 0}>
            Back
          </button>
          {step < screens.length - 1 ? (
            <button className="btn" onClick={goNext} disabled={!canNext}>
              Next
            </button>
          ) : (
            <button className="btn" onClick={() => alert("Done 🎉")} disabled>
              Done
            </button>
          )}
        </div>
      </div>

      {/* FAQ */}
      <section className="faq">
        <h2 className="faq__title">FAQ</h2>

        <details className="faq__item" open>
          <summary>How long does the event last?</summary>
          <p>
            This claim event continues <b>until all 7,777,000 OXP tokens are fully distributed</b>.
            Once the claim wallet runs out, the event will automatically close.
          </p>
        </details>

        <details className="faq__item">
          <summary>Can one person claim multiple times?</summary>
          <p>
            No. Google ID, X account, and wallet address are cross-verified to allow only{" "}
            <b>1 claim per user</b>. This helps <b>prevent bots</b> and ensures the tokens go to{" "}
            <b>real participants</b>.
          </p>
        </details>

        <details className="faq__item">
          <summary>What if I receive a voucher but don’t claim?</summary>
          <p>
            Vouchers have an <b>expiration time</b>. If you don’t claim before it expires, it
            becomes invalid and no tokens will be sent.
          </p>
        </details>

        <details className="faq__item">
          <summary>Do I need to pay gas fees?</summary>
          <p>
            It’s not actually a <b>gas fee</b> — it’s a small{" "}
            <b>ATA (Associated Token Account) creation fee</b> of around <b>0.002 SOL</b>. This SOL
            is <b>refundable</b>: if you later close the token account, the SOL is automatically
            returned to your wallet.
          </p>
        </details>

        <details className="faq__item">
          <summary>My wallet connection/signature doesn’t work.</summary>
          <p>
            Update your wallet (e.g., Phantom) to the latest version and check for hidden pop-ups.
            If issues persist, restart your browser and try again.
          </p>
        </details>
      </section>

      {/* Dev Test Panel */}
      <section className="debug">
        <h3>Dev Test Panel</h3>
        <button className="btn btn--ghost" onClick={testHealth}>
          Test /api/health
        </button>
        <pre className="log">{log.join("\n")}</pre>
      </section>
    </div>
  );
}